use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let data = input.as_array().unwrap();
    let mut result = Vec::new();
    let mut last_key = String::new();
    let mut last_value = i64::MIN;

    for item in data {
        let key = item.as_array().unwrap().get(0).unwrap().as_i64().unwrap();
        let value = item.as_array().unwrap().get(1).unwrap().as_i64().unwrap();

        if key == last_key {
            last_value = value;
        } else {
            result.push(Value::Array(vec![Value::String(last_key), Value::Number(last_value as f64)]));
            last_key = key.to_string();
            last_value = value;
        }
    }

    result.push(Value::Array(vec![Value::String(last_key), Value::Number(last_value as f64)]));
    Value::Array(result)
}
